import os, random, subprocess, sys, time
from collections import deque

N = 2000
WALL, DOT, SCH, ECH, NL = 35, 46, 83, 69, 10
TBL = bytes(WALL if x < 64 else DOT for x in range(256))

def find_body():
    d = os.getcwd()
    for _ in range(5):
        if os.path.isfile(os.path.join(d, "maze.py")):
            return d
        p = os.path.dirname(d)
        if p == d:
            break
        d = p
    return os.getcwd()

BASE = find_body()
MAZE = os.path.join(BASE, "maze.py")

def run(data, timeout=20):
    t0 = time.perf_counter()
    try:
        p = subprocess.run([sys.executable, MAZE], input=data,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                           cwd=BASE, timeout=timeout)
    except Exception:
        return None, float("inf")
    dt = time.perf_counter() - t0
    if p.returncode != 0:
        return None, dt
    return p.stdout.strip(), dt

def ref(data):
    lines = data.splitlines()
    if not lines:
        return -1
    w = max(len(x) for x in lines)
    rows = [bytearray(line + b"#" * (w - len(line))) for line in lines]
    start = goal = None
    for r, row in enumerate(rows):
        for c, ch in enumerate(row):
            if ch == SCH and start is None:
                start = (r, c)
            elif ch == ECH and goal is None:
                goal = (r, c)
    if start is None or goal is None:
        return -1
    if start == goal:
        return 0
    q = deque([(start[0], start[1], 0)])
    seen = {start}
    h = len(rows)
    while q:
        r, c, d = q.popleft()
        nd = d + 1
        for nr, nc in ((r+1, c), (r-1, c), (r, c+1), (r, c-1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and rows[nr][nc] != WALL:
                if (nr, nc) == goal:
                    return nd
                seen.add((nr, nc))
                q.append((nr, nc, nd))
    return -1

def make_big(seed, reachable):
    rng = random.Random(seed)
    raw = rng.randbytes(N * N)
    cells = raw.translate(TBL)
    stride = N + 1
    buf = bytearray(N * stride)
    for r in range(N):
        off = r * stride
        buf[off:off+N] = cells[r*N:(r+1)*N]
        buf[off+N] = NL
    # A seeded random maze with a guaranteed giant connected component.
    dots = b"." * N
    for r in range(0, N, 2):
        buf[r*stride:r*stride+N] = dots
    for r in range(N):
        buf[r*stride] = DOT
    if reachable:
        # Manhattan distance is a lower bound; this random monotone corridor attains it.
        r = c = 0
        while r < N-1 or c < N-1:
            if r == N-1:
                c += 1
            elif c == N-1:
                r += 1
            elif rng.getrandbits(1):
                r += 1
            else:
                c += 1
            buf[r*stride+c] = DOT
        buf[0] = SCH
        buf[(N-1)*stride+(N-1)] = ECH
        return bytes(buf), 2*N-2
    # Both in-grid neighbours of E are walls, so no path can exist.
    buf[0] = SCH
    buf[(N-2)*stride+(N-1)] = WALL
    buf[(N-1)*stride+(N-2)] = WALL
    buf[(N-1)*stride+(N-1)] = ECH
    return bytes(buf), -1

def main():
    if not os.path.isfile(MAZE):
        print(0)
        return
    cases = [
        (b"SE", 1), (b"S#E", -1), (b"S\nE", 1),
        (b"S.\n.#\n.E", 3), (b"####\n#S.#\n##.#\n..E#", 3),
        (b"S..\n###\n..E", -1), (b"..S\n...\nE..", 4),
        (b"", -1), (b"..E", -1),
    ]
    rng = random.Random(20240501)
    for _ in range(12):
        h, w = rng.randint(2, 12), rng.randint(2, 12)
        rows = [bytearray(WALL if rng.random() < 0.32 else DOT for _ in range(w)) for _ in range(h)]
        a, b = rng.sample(range(h*w), 2)
        rows[a//w][a%w] = SCH
        rows[b//w][b%w] = ECH
        data = b"\n".join(bytes(row) for row in rows)
        cases.append((data, ref(data)))
    for data, exp in cases:
        out, _ = run(data, 5)
        if out != str(exp).encode():
            print(0)
            return
    data_a, exp_a = make_big(1234567, True)
    data_b, exp_b = make_big(7654321, False)
    def timed(data, exp, reps=2):
        best = float("inf")
        for _ in range(reps):
            out, dt = run(data, 20)
            if out != str(exp).encode():
                return None
            if dt < best:
                best = dt
        return best
    ta = timed(data_a, exp_a)
    tb = timed(data_b, exp_b)
    if ta is None or tb is None or ta + tb <= 0:
        print(0)
        return
    print(f"{20000000.0/(ta+tb):.2f}")

try:
    main()
except Exception:
    print(0)
